def transform(grid):
    h, w = len(grid), len(grid[0])

    # Trace the vertical beam through the openings, joining paths between
    # consecutive barriers.
    out = [row[:] for row in grid]
    walls = [r for r in range(h) if 8 in grid[r]]
    seed = next(((r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == 2), None)
    if seed is None:
        return out

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = 2

    if not walls:
        return out

    active = [seed[1]]
    for i, r in enumerate(walls):
        holes = [c for c in range(w) if grid[r][c] == 0]
        if not holes:
            continue

        # Join the incoming beam to the openings at the barrier.
        joinrow = r - 1
        if joinrow >= 0:
            for c in range(min(active + holes), max(active + holes) + 1):
                paint(joinrow, c)
        for c in holes:
            paint(r, c)

        if i + 1 < len(walls):
            nr = walls[i + 1]
            # Rays continue down from every opening.
            for rr in range(r + 1, nr):
                for c in holes:
                    paint(rr, c)
            # When separated by multiple empty rows, the beam spreads
            # horizontally across the intervening corridor.
            if nr - r > 2:
                rr = nr - 1
                for c in range(w):
                    paint(rr, c)
        else:
            for rr in range(r + 1, h):
                for c in holes:
                    paint(rr, c)
        active = holes

    return out
